generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel 
       (SUM(?totalShortfall) AS ?categoryShortfall) 
       (SUM(?totalHoldingValue) AS ?categoryHoldingValue) 
       (AVG(?avgAllocationPct) AS ?categoryAvgAllocationPct) 
       (AVG(?avgLiquidityScore) AS ?categoryAvgLiquidity) 
       (AVG(?avgDiversificationScore) AS ?categoryAvgDiversification)
WHERE {
  # Category label
  ?cat a wm:Category .
  OPTIONAL { ?cat rdfs:label ?categoryLabel . }

  # Distinct investor‑to‑category mapping via holdings
  {
    SELECT DISTINCT ?investorId ?cat
    WHERE {
      ?phMap a wm:PortfolioHolding .
      ?phMap wm:investorId ?investorId .
      ?phMap wm:hasCategory ?cat .
    }
  }

  # Aggregate shortfall per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?totalShortfall)
    WHERE {
      ?ig a wm:InvestmentGoal .
      ?ig wm:investorId ?investorId .
      ?ig wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }

  # Aggregate holding value per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?ph a wm:PortfolioHolding .
      ?ph wm:investorId ?investorId .
      ?ph wm:currentValue ?holdingValue .
    }
    GROUP BY ?investorId
  }

  # Average allocation percentage per investor
  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?allocationPct)) AS ?avgAllocationPct)
    WHERE {
      ?sa a wm:SectorAllocation .
      ?sa wm:investorId ?investorId .
      ?sa wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }

  # Average liquidity and diversification scores per investor
  OPTIONAL {
    SELECT ?investorId 
           (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidityScore) 
           (AVG(xsd:decimal(?diversificationScore)) AS ?avgDiversificationScore)
    WHERE {
      ?phl a wm:PortfolioHealth .
      ?phl wm:investorId ?investorId .
      ?phl wm:liquidityScore ?liquidityScore .
      ?phl wm:diversificationScore ?diversificationScore .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?categoryLabel

